// 😀 The pending Source range crosses a cleanup call point.
class Box { n: i32 = 7; }

function observe(x: i32): i32 { return x; }
function echo(value: string): string { return value; }

export function pendingReference(x: i32): void {
  try { throw new Box(); }
  finally { observe(x); }
}

export function pendingScalar(x: i32): void {
  try { throw x; }
  finally { observe(x); }
}

export function stringEntry(): string {
  return echo("text");
}

@tsfgValue
class Wide { a: i32 = 1; b: i32 = 2; c: i32 = 3; }

export function pendingValue(value: Wide, x: i32): void {
  try { throw value; }
  finally { observe(x); }
}

